package vn.codegym;
import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.*;
@WebServlet("/currency") public class CurrencyServlet extends HttpServlet{protected void doGet(HttpServletRequest r,HttpServletResponse s)throws IOException{s.setContentType("text/html;charset=UTF-8");s.getWriter().print("<form method='post'><input type='number' step='0.01' name='usd' placeholder='USD' required><input type='number' name='rate' value='25000' required><button>Đổi sang VND</button></form>");}protected void doPost(HttpServletRequest r,HttpServletResponse s)throws IOException{s.setContentType("text/html;charset=UTF-8");double usd=Double.parseDouble(r.getParameter("usd")),rate=Double.parseDouble(r.getParameter("rate"));s.getWriter().printf("<h1>%.2f USD = %,.0f VND</h1>",usd,usd*rate);}}
